    "Osvalds": {
      "sources": [
        "https://periodika.lv/periodika2-viewer/#issue:/696041"
      ],
      "text": {
        "en": [
          "Osvalds belongs to the Old English Oswald family. Its elements os and weald are explained as “god” and “power”; an older account also paraphrases the name as “good ruler”.",
          "The dictionary gives the following historical record: Sigulda, 1638; calendar 1767. Recorded use and calendar inclusion are different kinds of evidence; neither is automatically a name-creation date."
        ],
        "lv": [
          "Osvalds pieder senangļu Oswald vārdu saimei. Sastāvdaļas os un weald skaidrotas kā «dievs» un «vara»; senāks skaidrojums vārdu pārstāsta arī kā «labs valdnieks».",
          "Vārdnīca dod šādu vēsturisku ierakstu: Sigulda, 1638; kalendārā 1767. Fiksēts lietojums un iekļaušana kalendārā ir atšķirīgas liecības; neviens datums automātiski nenozīmē vārda radīšanu."
        ],
        "ru": [
          "Osvalds относится к древнеанглийской группе Oswald. Элементы os и weald объясняются как «бог» и «власть»; более старое толкование также передаёт имя как «добрый правитель».",
          "Словарь приводит следующую историческую запись: Сигулда, 1638; календарь 1767. Употребление и включение в календарь — разные виды свидетельств; ни одна дата автоматически не означает создание имени."
        ],
        "lt": [
          "Osvalds priklauso senosios anglų kalbos Oswald vardų šeimai. Dėmenys os ir weald aiškinami kaip „dievas“ ir „galia“; senesniame aiškinime vardas dar perteikiamas kaip „geras valdovas“.",
          "Žodynas pateikia tokį istorinį įrašą: Sigulda, 1638; kalendoriuje 1767. Vartojimas ir įtraukimas į kalendorių yra skirtingi liudijimai; nė viena data savaime nereiškia vardo sukūrimo."
        ],
        "et": [
          "Osvalds kuulub vanainglise Oswaldi nimeperre. Osad os ja weald on seletatud kui „jumal” ja „võim”; vanem seletus annab ka tähenduse „hea valitseja”.",
          "Sõnastik annab järgmise ajaloolise kirje: Sigulda, 1638; kalendris 1767. Kasutus ja kalendrisse lisamine on eri liiki tõendid; kumbki daatum ei tähenda automaatselt nime loomist."
        ]
      },
      "calendar_entry_year": 1767
    },
