    "Remberts": {
      "sources": [
        "https://periodika.lv/periodika2-viewer/#issue:/696041"
      ],
      "text": {
        "en": [
          "Klāvs Siliņš’s dictionary (1990) explains Remberts through the Old High German components ragin + beraht. Their meanings are, respectively: divine decree; shining, famous.",
          "The dictionary gives the following historical record: Vidzeme, 1545; calendar 1874. Recorded use and calendar inclusion are different kinds of evidence; neither is automatically a name-creation date."
        ],
        "lv": [
          "Klāva Siliņa vārdnīca (1990) Remberts skaidro ar senaugšvācu sastāvdaļām ragin + beraht. To nozīmes attiecīgi ir: dievu lēmums; spīdošs, slavens.",
          "Vārdnīca dod šādu vēsturisku ierakstu: Vidzeme, 1545; kalendārā 1874. Fiksēts lietojums un iekļaušana kalendārā ir atšķirīgas liecības; neviens datums automātiski nenozīmē vārda radīšanu."
        ],
        "ru": [
          "Словарь Клавса Силиньша (1990) объясняет Remberts через древневерхненемецкие компоненты ragin + beraht. Их значения соответственно: решение богов; сияющий, славный.",
          "Словарь приводит следующую историческую запись: Видземе, 1545; календарь 1874. Употребление и включение в календарь — разные виды свидетельств; ни одна дата автоматически не означает создание имени."
        ],
        "lt": [
          "Klāvo Siliņšo žodynas (1990) Remberts aiškina senosios vokiečių aukštaičių kalbos dėmenimis ragin + beraht. Jų reikšmės atitinkamai: dievų sprendimas; spindintis, garsus.",
          "Žodynas pateikia tokį istorinį įrašą: Vidžemė, 1545; kalendoriuje 1874. Vartojimas ir įtraukimas į kalendorių yra skirtingi liudijimai; nė viena data savaime nereiškia vardo sukūrimo."
        ],
        "et": [
          "Klāvs Siliņši sõnastik (1990) seletab nime Remberts vanakõrgsaksa osadega ragin + beraht. Nende tähendused on vastavalt: jumalate otsus; särav, kuulus.",
          "Sõnastik annab järgmise ajaloolise kirje: Liivimaa (Vidzeme), 1545; kalendris 1874. Kasutus ja kalendrisse lisamine on eri liiki tõendid; kumbki daatum ei tähenda automaatselt nime loomist."
        ]
      }
    },
