    "Laurentijs": {
      "sources": [
        "https://periodika.lv/periodika2-viewer/#issue:/696041"
      ],
      "text": {
        "en": [
          "Laurentijs belongs to Latin Laurentius, originally “a man from Laurentum”, a town near Rome. A later interpretation connects the name with being crowned with laurel.",
          "The dictionary gives the following historical record: Riga, 1406; calendar 1851. Recorded use and calendar inclusion are different kinds of evidence; neither is automatically a name-creation date. The spelling and context of the original historical record have not been independently inspected; its date is not proof of modern orthography."
        ],
        "lv": [
          "Laurentijs pieder latīņu Laurentius saimei, sākotnēji «vīrs no Laurentas» — pilsētas Romas tuvumā. Vēlāks skaidrojums vārdu saista ar lauru vainagu.",
          "Vārdnīca dod šādu vēsturisku ierakstu: Rīga, 1406; kalendārā 1851. Fiksēts lietojums un iekļaušana kalendārā ir atšķirīgas liecības; neviens datums automātiski nenozīmē vārda radīšanu. Vēsturiskā oriģinālieraksta rakstība un konteksts nav neatkarīgi pārbaudīti; tā datums nepierāda mūsdienu ortogrāfiju."
        ],
        "ru": [
          "Laurentijs относится к латинскому Laurentius: первоначально «мужчина из Лаврента», города близ Рима. Позднее имя также связывали с увенчанием лавром.",
          "Словарь приводит следующую историческую запись: Рига, 1406; календарь 1851. Употребление и включение в календарь — разные виды свидетельств; ни одна дата автоматически не означает создание имени. Написание и контекст оригинальной исторической записи отдельно не проверены; её дата не доказывает современную орфографию."
        ],
        "lt": [
          "Laurentijs priklauso lotyniško Laurentius šeimai: iš pradžių „vyras iš Laurento“, miesto netoli Romos. Vėlesnis aiškinimas vardą sieja su vainikavimu laurais.",
          "Žodynas pateikia tokį istorinį įrašą: Ryga, 1406; kalendoriuje 1851. Vartojimas ir įtraukimas į kalendorių yra skirtingi liudijimai; nė viena data savaime nereiškia vardo sukūrimo. Originalaus istorinio įrašo rašyba ir kontekstas atskirai netikrinti; jo data neįrodo šiuolaikinės ortografijos."
        ],
        "et": [
          "Laurentijs kuulub ladina Laurentiuse nimeperre, algselt „mees Laurentumist”, Rooma lähedal asuvast linnast. Hilisem tõlgendus seob nime loorberiga pärgamisega.",
          "Sõnastik annab järgmise ajaloolise kirje: Riia, 1406; kalendris 1851. Kasutus ja kalendrisse lisamine on eri liiki tõendid; kumbki daatum ei tähenda automaatselt nime loomist. Algse ajaloolise kirje kirjapilti ja konteksti pole eraldi kontrollitud; selle daatum ei tõenda tänapäevast ortograafiat."
        ]
      },
      "calendar_entry_year": 1851
    },
