    "Rudīte": {
      "sources": [
        "https://periodika.lv/periodika2-viewer/#issue:/696041"
      ],
      "text": {
        "en": [
          "Rudīte is linked to the Latvian word ruds or rudens. The dictionary records a word-based name formation; it does not identify a particular person as the inventor of the name.",
          "The dictionary gives the following historical record: Dobele, 1912; calendar 1915. Recorded use and calendar inclusion are different kinds of evidence; neither is automatically a name-creation date."
        ],
        "lv": [
          "Rudīte saistīts ar latviešu vārdu ruds or rudens. Vārdnīca fiksē personvārda darināšanu no valodas vārda, bet nenosauc konkrētu cilvēku par šī vārda izgudrotāju.",
          "Vārdnīca dod šādu vēsturisku ierakstu: Dobele, 1912; kalendārā 1915. Fiksēts lietojums un iekļaušana kalendārā ir atšķirīgas liecības; neviens datums automātiski nenozīmē vārda radīšanu."
        ],
        "ru": [
          "Rudīte связано с латышским словом ruds or rudens. Словарь фиксирует образование личного имени от слова языка, но не называет конкретного человека изобретателем имени.",
          "Словарь приводит следующую историческую запись: Добеле, 1912; календарь 1915. Употребление и включение в календарь — разные виды свидетельств; ни одна дата автоматически не означает создание имени."
        ],
        "lt": [
          "Rudīte siejamas su latvių žodžiu ruds or rudens. Žodynas fiksuoja asmenvardžio darybą iš kalbos žodžio, tačiau nenurodo konkretaus žmogaus kaip šio vardo išradėjo.",
          "Žodynas pateikia tokį istorinį įrašą: Dobele, 1912; kalendoriuje 1915. Vartojimas ir įtraukimas į kalendorių yra skirtingi liudijimai; nė viena data savaime nereiškia vardo sukūrimo."
        ],
        "et": [
          "Rudīte on seotud läti sõnaga ruds or rudens. Sõnastik dokumenteerib isikunime moodustamist keelesõnast, kuid ei nimeta üht kindlat inimest selle nime loojaks.",
          "Sõnastik annab järgmise ajaloolise kirje: Dobele, 1912; kalendris 1915. Kasutus ja kalendrisse lisamine on eri liiki tõendid; kumbki daatum ei tähenda automaatselt nime loomist."
        ]
      }
    },
    "Everts": {
      "sources": [
        "https://personvardi.lu.lv/lv/personvards/258"
      ],
      "text": {
        "en": [
          "Everts is a shortened form of Eberhards, made through Low German Everhard. The short form also arose in Low German, where spellings such as Evert and Ewert are recorded from at least the early 13th century.",
          "The dictionary’s historical records include Evert Meislaw in Viskaļi and Evert Gulve in Svirlauka in 1566. Those are the source spellings Evert; they document the name family and must not be presented as 1566 records of today’s spelling Everts."
        ],
        "lv": [
          "Everts ir Eberhards īsforma, kas veidota caur lejasvācu Everhard. Arī īsforma radusies lejasvācu valodā, kur Evert un Ewert tipa rakstības zināmas vismaz kopš 13. gadsimta sākuma.",
          "Vārdnīcas vēsturiskajos datos 1566. gadā minēti Evert Meislaw Viskaļos un Evert Gulve Svirlaukā. Avota rakstība ir Evert; tā dokumentē vārdu saimi, nevis mūsdienu rakstības Everts lietojumu 1566. gadā."
        ],
        "ru": [
          "Everts — сокращённая форма Eberhards, возникшая через нижненемецкое Everhard. Само сокращение также появилось в нижненемецком: написания Evert и Ewert известны как минимум с начала XIII века.",
          "В исторических данных словаря за 1566 год упомянуты Evert Meislaw в Вискали и Evert Gulve в Свирлауке. В источнике написано Evert; это свидетельство о группе имён, а не запись современного Everts за 1566 год."
        ],
        "lt": [
          "Everts yra Eberhards trumpinys, susidaręs per žemutinės vokiečių kalbos Everhard. Trumpinys taip pat atsirado žemutinėje vokiečių kalboje, kur Evert ir Ewert tipo rašybos žinomos bent nuo XIII amžiaus pradžios.",
          "Žodyno istoriniuose duomenyse 1566 metais minimi Evert Meislaw Viskaļiuose ir Evert Gulve Svirlaukoje. Šaltinio rašyba yra Evert; ji liudija vardų šeimą, o ne dabartinės Everts rašybos vartojimą 1566 metais."
        ],
        "et": [
          "Everts on Eberhardsi lühend, mis kujunes alamsaksa Everhardi kaudu. Ka lühend ise tekkis alamsaksa keeles, kus Everti ja Ewerti laadseid kirjapilte tuntakse vähemalt 13. sajandi algusest.",
          "Sõnastiku ajalooandmetes leiduvad 1566. aastal Evert Meislaw Viskaļis ja Evert Gulve Svirlaukas. Allika kirjakuju on Evert; see tõendab nimepere kasutust, mitte tänapäevase Evertsi kirjapilti 1566. aastal."
        ]
      }
    },
