          "Žodynas pateikia tokį istorinį įrašą: Vidžemė, XIX amžiaus antrasis ketvirtis; kalendoriuje 1928. Vartojimas ir įtraukimas į kalendorių yra skirtingi liudijimai; nė viena data savaime nereiškia vardo sukūrimo."
