    "Klaara": {
      "sources": [
        "https://dspace.ut.ee/bitstreams/87883b84-6f77-4dfe-b2ac-95447f6f436a/download"
      ],
      "text": {
        "en": [
          "Klaara belongs to the Clara family, connected with Latin clara, “clear, bright”. The Estonian forms are recorded alongside the international name; the Latin adjective is not a description of a bearer’s personality.",
          "Rajandi reports one girl named Klaara in the 1963 birth records. This is an exact-spelling historical use, not a first-ever attestation or a current population count."
        ],
        "lv": [
          "Klaara pieder Clara saimei, kas saistīta ar latīņu clara «skaidra, gaiša». Igauņu formas fiksētas līdzās starptautiskajam vārdam; latīņu īpašības vārds nav nesējas rakstura apraksts.",
          "Rajandi ziņo par vienu meiteni ar vārdu Klaara 1963. gada dzimšanas ierakstos. Tas ir šīs rakstības vēsturisks lietojums, nevis pirmais pieminējums vispār vai pašreizējs iedzīvotāju skaits."
        ],
        "ru": [
          "Klaara относится к группе Clara, связанной с латинским clara «ясная, светлая». Эстонские формы записаны рядом с международным именем; латинское прилагательное не описывает характер носительницы.",
          "Раянди сообщает об одной девочке по имени Klaara в записях о рождениях 1963 года. Это историческое употребление данного написания, а не первое упоминание вообще или современная численность."
        ],
        "lt": [
          "Klaara priklauso Clara šeimai, siejamai su lotynų clara „aiški, šviesi“. Estiškos formos užfiksuotos greta tarptautinio vardo; lotyniškas būdvardis neapibūdina turėtojos asmenybės.",
          "Rajandi nurodo vieną mergaitę vardu Klaara 1963 metų gimimų įrašuose. Tai tikslus šios rašybos istorinis vartojimas, o ne pats pirmasis paminėjimas ar dabartinis gyventojų skaičius."
        ],
        "et": [
          "Klaara kuulub Clara nimeperre, mis on seotud ladina sõnaga clara „selge, kirgas”. Eesti kujud on kirja pandud rahvusvahelise nime kõrval; ladina omadussõna ei kirjelda kandja iseloomu.",
          "Rajandi märgib 1963. aasta sünnikirjetes üht tüdrukut nimega Klaara. See on täpse kirjapildi ajalooline kasutus, mitte esmamaining ega tänapäevane rahvaarv."
        ]
      }
    },
