    "Sven": {
      "sources": [
        "https://dspace.ut.ee/bitstreams/87883b84-6f77-4dfe-b2ac-95447f6f436a/download"
      ],
      "text": {
        "en": [
          "Sven is connected with Old Scandinavian svend, explained as “young man, son” or “squire”. The Finnish related form is Soini; the older Estonian record Sveno is a separate spelling.",
          "In Tallinn in 1962, Sven accounted for eight per thousand in the birth-name sample reported by Rajandi. This describes that historical local sample, not a present-day national count or the first appearance of the name."
        ],
        "lv": [
          "Sven saistīts ar senskandināvu svend, ko skaidro kā «jauneklis, dēls» vai «ieroču nesējs». Somu radniecīgā forma ir Soini; senākais igauņu ieraksts Sveno ir cita rakstība.",
          "Tallinā 1962. gadā Sven bija astoņi uz tūkstoti Rajandi aprakstītajā jaundzimušo vārdu izlasē. Tas raksturo konkrēto vēsturisko vietējo izlasi, nevis pašreizēju valsts skaitu vai vārda pirmo parādīšanos."
        ],
        "ru": [
          "Sven связывается с древнескандинавским svend «юноша, сын» или «оруженосец». Финская родственная форма — Soini; более старая эстонская запись Sveno имеет другое написание.",
          "В таллинской выборке имён новорождённых за 1962 год Sven составляло восемь на тысячу, по данным Раянди. Это местная историческая выборка, а не современная численность по стране или первое появление имени."
        ],
        "lt": [
          "Sven siejamas su senosios skandinavų kalbos svend „jaunuolis, sūnus“ arba „ginklanešys“. Suomiška gimininga forma yra Soini; senesnis estiškas Sveno įrašas yra kita rašyba.",
          "Talino 1962 metų naujagimių vardų imtyje Sven sudarė aštuonis iš tūkstančio, kaip nurodo Rajandi. Tai vietinė istorinė imtis, o ne dabartinis šalies skaičius ar pirmasis vardo pasirodymas."
        ],
        "et": [
          "Sven on seotud vanaskandinaavia sõnaga svend „nooruk, poeg” või „relvakandja”. Soome vastav kuju on Soini; vanem Eesti kirje Sveno on eraldi kirjapilt.",
          "Rajandi esitatud Tallinna 1962. aasta sünninimede valimis oli Sven kaheksal poisil tuhandest. See kirjeldab ajaloolist kohalikku valimit, mitte tänapäevast üleriigilist arvu ega nime esmamainingut."
        ]
      }
    },
